def discussion_thread(
    self, course_id: int | str, topic_id: int | str, *, unread_only: bool = False
) -> dict[str, Any]:
    """Read the cached discussion tree with explicit read state and reply context."""
    from canvaspilot.discussion_thread import (
        build_discussion_thread,
        validate_discussion_selection,
    )

    course, topic = validate_discussion_selection(course_id, topic_id, unread_only)
    result = self.get_discussion(course, topic)
    return build_discussion_thread(result["topic"], result["view"], unread_only=unread_only)

elif args.cmd == "discussion":
    import httpx

    from canvaspilot.client import CanvasAuthError

    try:
        result = api.discussion_thread(
            args.course_id, args.topic_id, unread_only=args.unread_only
        )
    except (CanvasAuthError, httpx.HTTPError, ValueError) as error:
        print(json.dumps({
            "ok": False, "error": type(error).__name__, "message": str(error),
        }), file=sys.stderr)
        raise SystemExit(1) from None
    print(json.dumps(result, indent=2))

@mcp.tool(
    description=(
        "Read a Canvas cached discussion tree with source entry fields, author attribution "
        "and reported read markers. unread_only retains known unread entries and their "
        "ancestors as context. The cached view is eventually consistent; unknown or "
        "unlocated read markers remain explicit. Does not post or mark entries read."
    ),
    annotations=ToolAnnotations(readOnlyHint=True, destructiveHint=False),
    structured_output=False,
)
async def canvas_discussion_thread(
    course_id: str, topic_id: str, unread_only: StrictBool = False
) -> str:
    return _dump(_get_api().discussion_thread(course_id, topic_id, unread_only=unread_only))
